import { useCallback, useEffect, useState } from 'react';

import { Training } from 'pages/trainingHub/domain';

const STORAGE_KEY = 'recent-trainings';
const MAX_ITEMS = 2;

export function useRecentTrainings() {
  const [recentTrainings, setRecentTrainings] = useState<Training[]>([]);

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY);

    if (!stored) return;

    try {
      setRecentTrainings(JSON.parse(stored));
    } catch {
      localStorage.removeItem(STORAGE_KEY);
    }
  }, []);

  const addRecentTraining = useCallback((training: Training) => {
    setRecentTrainings((current) => {
      const updated = [
        {
          ...training,
          accessedAt: new Date().toISOString(),
        },
        ...current.filter((item) => item.id !== training.id),
      ].slice(0, MAX_ITEMS);

      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));

      return updated;
    });
  }, []);

  const clearRecentTrainings = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY);
    setRecentTrainings([]);
  }, []);

  return {
    recentTrainings,
    addRecentTraining,
    clearRecentTrainings,
  };
}
